// Package apps manages tenant applications and their OAuth 2.0 / OpenID Connect clients (ADR-0013). Client secrets
// are generated by Porch, shown once and stored only as HMACs under the keyring token key.
package apps

import (
	"context"
	"crypto/hmac"
	"database/sql"
	"encoding/json"
	"errors"
	"net"
	"net/url"
	"slices"
	"strings"
	"time"

	"github.com/aurimasniekis/go-porch/internal/apperr"
	"github.com/aurimasniekis/go-porch/internal/audit"
	"github.com/aurimasniekis/go-porch/internal/domain"
	"github.com/aurimasniekis/go-porch/internal/ids"
	"github.com/aurimasniekis/go-porch/internal/keyring"
	"github.com/aurimasniekis/go-porch/internal/outbox"
	"github.com/aurimasniekis/go-porch/internal/session"
	"github.com/aurimasniekis/go-porch/internal/store"
	"github.com/aurimasniekis/go-porch/internal/store/db"
	"github.com/aurimasniekis/go-porch/internal/tenancy"
)

// Application kinds.
const (
	KindOIDC        = "oidc"
	KindForwardAuth = "forward_auth"
)

// Disclosure controls optional claims released to an application.
type Disclosure struct {
	Email        bool `json:"email"`
	Groups       bool `json:"groups"`
	Roles        bool `json:"roles"`
	Entitlements bool `json:"entitlements"`
}

// Application is something users open.
type Application struct {
	ID            string     `json:"id"`
	TenantID      string     `json:"tenant_id"`
	Slug          string     `json:"slug"`
	Name          string     `json:"name"`
	Kind          string     `json:"kind"`
	Description   string     `json:"description"`
	LaunchURL     string     `json:"launch_url"`
	Enabled       bool       `json:"enabled"`
	Disclosure    Disclosure `json:"disclosure"`
	Version       int64      `json:"version"`
	ManagedBy     string     `json:"managed_by"`
	LastChangedBy string     `json:"last_changed_by,omitempty"`
	CreatedAt     time.Time  `json:"created_at"`
	UpdatedAt     time.Time  `json:"updated_at"`
}

// Client is an OAuth client (secret never included).
type Client struct {
	ID              string   `json:"client_id"`
	TenantID        string   `json:"tenant_id"`
	AppID           string   `json:"app_id"`
	Type            string   `json:"client_type"`
	ApplicationType string   `json:"application_type"`
	SecretHint      string   `json:"secret_hint,omitempty"`
	RedirectURIs    []string `json:"redirect_uris"`
	PostLogoutURIs  []string `json:"post_logout_redirect_uris"`
	GrantTypes      []string `json:"grant_types"`
	AllowedScopes   []string `json:"allowed_scopes"`
	Audiences       []string `json:"audiences"`
	AllowedOrigins  []string `json:"allowed_origins"`
	RequirePKCE     bool     `json:"require_pkce"`
	SigningAlg      string   `json:"signing_alg"`
	AccessTokenTTL  int64    `json:"access_token_ttl_seconds"`
	IDTokenTTL      int64    `json:"id_token_ttl_seconds"`
	RefreshTTL      int64    `json:"refresh_ttl_seconds"`
	RefreshIdle     int64    `json:"refresh_idle_seconds"`
	Version         int64    `json:"version"`
}

func jsonList(s string) []string {
	var out []string
	_ = json.Unmarshal([]byte(s), &out)
	if out == nil {
		out = []string{}
	}
	return out
}

func mustJSON(v any) string {
	b, _ := json.Marshal(v)
	return string(b)
}

// AppFromRow converts a row.
func AppFromRow(r db.Application) Application {
	var d Disclosure
	_ = json.Unmarshal([]byte(r.DisclosureJson), &d)
	return Application{ID: r.ID, TenantID: r.TenantID, Slug: r.Slug, Name: r.Name, Kind: r.Kind, Description: r.Description, LaunchURL: r.LaunchUrl,
		Enabled: r.Enabled == 1, Disclosure: d, Version: r.Version, ManagedBy: r.ManagedBy, LastChangedBy: r.LastChangedBy.String,
		CreatedAt: domain.FromMicros(r.CreatedAt), UpdatedAt: domain.FromMicros(r.UpdatedAt)}
}

// ClientFromRow converts a row.
func ClientFromRow(r db.OauthClient) Client {
	return Client{ID: r.ID, TenantID: r.TenantID, AppID: r.AppID, Type: r.ClientType, ApplicationType: r.ApplicationType, SecretHint: r.SecretHint,
		RedirectURIs: jsonList(r.RedirectUris), PostLogoutURIs: jsonList(r.PostLogoutUris), GrantTypes: jsonList(r.GrantTypes),
		AllowedScopes: jsonList(r.AllowedScopes), Audiences: jsonList(r.Audiences), AllowedOrigins: jsonList(r.AllowedOrigins),
		RequirePKCE: r.RequirePkce == 1, SigningAlg: r.SigningAlg, AccessTokenTTL: r.AccessTokenTtlSecs, IDTokenTTL: r.IDTokenTtlSecs,
		RefreshTTL: r.RefreshTtlSecs, RefreshIdle: r.RefreshIdleSecs, Version: r.Version}
}

// Service manages applications and clients.
type Service struct {
	s     *store.Store
	kr    *keyring.Keyring
	audit *audit.Writer
	// AllowInsecureRedirects permits http:// redirect URIs on non-loopback hosts (development only).
	AllowInsecureRedirects bool
}

// New returns a service.
func New(s *store.Store, kr *keyring.Keyring, a *audit.Writer) *Service {
	return &Service{s: s, kr: kr, audit: a}
}

// Errors.
var (
	ErrAppNotFound    = apperr.New(apperr.CodeNotFound, "application not found")
	ErrClientNotFound = apperr.New(apperr.CodeNotFound, "client not found")
)

// ClientParams configure an OIDC client.
type ClientParams struct {
	Type            string // confidential | public
	ApplicationType string // web | native | user_agent
	RedirectURIs    []string
	PostLogoutURIs  []string
	GrantTypes      []string
	AllowedScopes   []string
	Audiences       []string
	AllowedOrigins  []string
	RequirePKCE     *bool
	SigningAlg      string
	AccessTokenTTL  time.Duration
	IDTokenTTL      time.Duration
	RefreshTTL      time.Duration
	RefreshIdle     time.Duration
}

var knownGrants = []string{"authorization_code", "refresh_token", "client_credentials"}
var knownScopes = []string{"openid", "profile", "email", "offline_access", "groups"}

func (svc *Service) validateRedirect(field, raw, appType string, v *apperr.Validation) {
	u, err := url.Parse(raw)
	if err != nil || u.Scheme == "" || u.Fragment != "" || u.User != nil || strings.ContainsAny(raw, "*\\ ") || len(raw) > 2048 {
		v.Add(field, "%q must be an absolute URI without fragment, wildcard or credentials", raw)
		return
	}
	switch u.Scheme {
	case "https":
		if u.Host == "" {
			v.Add(field, "%q has no host", raw)
		}
	case "http":
		host := u.Hostname()
		ip := net.ParseIP(host)
		loopback := host == "localhost" || (ip != nil && ip.IsLoopback())
		if !loopback && !svc.AllowInsecureRedirects {
			v.Add(field, "%q must use https (http is allowed only for loopback)", raw)
		}
	default:
		if appType != "native" {
			v.Add(field, "%q: custom schemes are allowed only for native clients", raw)
		}
	}
}

func (svc *Service) validateClient(p *ClientParams, v *apperr.Validation) {
	if p.Type != "confidential" && p.Type != "public" {
		v.Add("client_type", "must be confidential or public")
	}
	if p.ApplicationType == "" {
		p.ApplicationType = "web"
	}
	if !slices.Contains([]string{"web", "native", "user_agent"}, p.ApplicationType) {
		v.Add("application_type", "must be web, native or user_agent")
	}
	if len(p.GrantTypes) == 0 {
		p.GrantTypes = []string{"authorization_code"}
	}
	for _, g := range p.GrantTypes {
		if !slices.Contains(knownGrants, g) {
			v.Add("grant_types", "unsupported grant %q (implicit and password grants are not offered)", g)
		}
	}
	if slices.Contains(p.GrantTypes, "client_credentials") && p.Type != "confidential" {
		v.Add("grant_types", "client_credentials needs a confidential client")
	}
	if slices.Contains(p.GrantTypes, "authorization_code") && len(p.RedirectURIs) == 0 {
		v.Add("redirect_uris", "at least one redirect URI is required for authorization_code")
	}
	for _, r := range p.RedirectURIs {
		svc.validateRedirect("redirect_uris", r, p.ApplicationType, v)
	}
	for _, r := range p.PostLogoutURIs {
		svc.validateRedirect("post_logout_redirect_uris", r, p.ApplicationType, v)
	}
	if len(p.AllowedScopes) == 0 {
		p.AllowedScopes = []string{"openid", "profile", "email", "offline_access"}
	}
	for _, s := range p.AllowedScopes {
		if !slices.Contains(knownScopes, s) {
			v.Add("allowed_scopes", "unknown scope %q", s)
		}
	}
	for _, a := range p.Audiences {
		if u, err := url.Parse(a); err != nil || len(a) > 512 || (u.Scheme != "" && u.Host == "") || strings.TrimSpace(a) != a || a == "" {
			v.Add("audiences", "%q is not a valid audience (use an absolute URI or a short identifier)", a)
		}
	}
	for _, o := range p.AllowedOrigins {
		u, err := url.Parse(o)
		if err != nil || (u.Scheme != "https" && u.Scheme != "http") || u.Host == "" || u.Path != "" || u.RawQuery != "" {
			v.Add("allowed_origins", "%q must be an origin like https://app.example.com", o)
		}
	}
	if p.SigningAlg == "" {
		p.SigningAlg = "ES256"
	}
	if p.SigningAlg != "ES256" && p.SigningAlg != "RS256" {
		v.Add("signing_alg", "must be ES256 or RS256")
	}
	def := func(d *time.Duration, def, lo, hi time.Duration, field string) {
		if *d == 0 {
			*d = def
		}
		if *d < lo || *d > hi {
			v.Add(field, "must be within %s..%s", lo, hi)
		}
	}
	def(&p.AccessTokenTTL, 10*time.Minute, time.Minute, time.Hour, "access_token_ttl_seconds")
	def(&p.IDTokenTTL, 10*time.Minute, time.Minute, time.Hour, "id_token_ttl_seconds")
	def(&p.RefreshTTL, 30*24*time.Hour, time.Hour, 365*24*time.Hour, "refresh_ttl_seconds")
	def(&p.RefreshIdle, 14*24*time.Hour, time.Hour, p.RefreshTTL, "refresh_idle_seconds")
}

// CreateParams describe an application.
type CreateParams struct {
	Slug        string
	Name        string
	Kind        string
	Description string
	LaunchURL   string
	Disclosure  *Disclosure
	Client      *ClientParams // required for kind oidc
}

// Created is a new application; Secret is set (once) for confidential clients.
type Created struct {
	App    Application
	Client *Client
	Secret string
}

func (svc *Service) newSecret() (secret string, mac []byte, hint string, err error) {
	r, err := session.RandomToken()
	if err != nil {
		return "", nil, "", err
	}
	secret = "porch_cs_" + r
	mac, err = svc.kr.MAC(keyring.PurposeToken, []byte("porch/client-secret/v1|"+secret))
	return secret, mac, secret[len(secret)-4:], err
}

// VerifySecret checks a client secret in constant time against every non-retired token key version.
func (svc *Service) VerifySecret(c db.OauthClient, secret string) bool {
	if c.ClientType != "confidential" || len(c.SecretMac) == 0 || secret == "" || len(secret) > 256 {
		return false
	}
	macs, err := svc.kr.MACAll(keyring.PurposeToken, []byte("porch/client-secret/v1|"+secret))
	if err != nil {
		return false
	}
	ok := false
	for _, m := range macs {
		if hmac.Equal(m, c.SecretMac) {
			ok = true
		}
	}
	return ok
}

// Create adds an application (and its client for kind oidc) to the scoped tenant.
func (svc *Service) Create(ctx context.Context, ch domain.Change, sc tenancy.Scope, p CreateParams) (Created, error) {
	if !sc.Valid() {
		return Created{}, tenancy.ErrNoAccess
	}
	var v apperr.Validation
	if !domain.ValidSlug(p.Slug) {
		v.Add("slug", "must be lowercase letters, digits or inner hyphens")
	}
	p.Name = domain.CleanName("name", p.Name, &v)
	if p.Kind != KindOIDC && p.Kind != KindForwardAuth {
		v.Add("kind", "must be oidc or forward_auth")
	}
	if p.LaunchURL != "" {
		if u, err := url.Parse(p.LaunchURL); err != nil || (u.Scheme != "https" && u.Scheme != "http") || u.Host == "" {
			v.Add("launch_url", "must be an http(s) URL")
		}
	}
	if p.Kind == KindOIDC {
		if p.Client == nil {
			v.Add("client", "is required for oidc applications")
		} else {
			svc.validateClient(p.Client, &v)
		}
	}
	if err := v.Err(); err != nil {
		return Created{}, err
	}
	disc := Disclosure{Email: true, Roles: true}
	if p.Disclosure != nil {
		disc = *p.Disclosure
	}
	var out Created
	var secretMAC []byte
	var hint string
	if p.Client != nil && p.Client.Type == "confidential" {
		var err error
		if out.Secret, secretMAC, hint, err = svc.newSecret(); err != nil {
			return Created{}, err
		}
	}
	err := svc.s.W().TxNamed(ctx, "apps.create", func(tx *store.Tx) error {
		id := ids.New(ids.Application)
		err := tx.Q.InsertApplication(ctx, db.InsertApplicationParams{ID: id, TenantID: sc.TenantID(), Slug: p.Slug, Name: p.Name, Kind: p.Kind,
			Description: p.Description, LaunchUrl: p.LaunchURL, Enabled: 1, DisclosureJson: mustJSON(disc), ManagedBy: ch.Managed(),
			LastChangedBy: domain.NullStr(ch.ChangedBy()), CreatedAt: tx.NowMicros(), UpdatedAt: tx.NowMicros()})
		if store.IsConstraint(err) {
			return apperr.New(apperr.CodeAlreadyExists, "application slug %q is taken in this tenant", p.Slug)
		}
		if err != nil {
			return err
		}
		if p.Client != nil {
			c := p.Client
			cid := ids.New(ids.OAuthClient)
			pkce := int64(1)
			if c.RequirePKCE != nil && !*c.RequirePKCE {
				if c.Type == "public" {
					return apperr.New(apperr.CodeInvalid, "public clients always require PKCE")
				}
				pkce = 0
			}
			err = tx.Q.InsertClient(ctx, db.InsertClientParams{ID: cid, TenantID: sc.TenantID(), AppID: id, ClientType: c.Type, ApplicationType: c.ApplicationType,
				SecretMac: secretMAC, SecretHint: hint, RedirectUris: mustJSON(nonNil(c.RedirectURIs)), PostLogoutUris: mustJSON(nonNil(c.PostLogoutURIs)),
				GrantTypes: mustJSON(c.GrantTypes), AllowedScopes: mustJSON(c.AllowedScopes), Audiences: mustJSON(nonNil(c.Audiences)),
				AllowedOrigins: mustJSON(nonNil(c.AllowedOrigins)), RequirePkce: pkce, SigningAlg: c.SigningAlg,
				AccessTokenTtlSecs: int64(c.AccessTokenTTL / time.Second), IDTokenTtlSecs: int64(c.IDTokenTTL / time.Second),
				RefreshTtlSecs: int64(c.RefreshTTL / time.Second), RefreshIdleSecs: int64(c.RefreshIdle / time.Second),
				CreatedAt: tx.NowMicros(), UpdatedAt: tx.NowMicros()})
			if err != nil {
				return err
			}
			cr, err := tx.Q.GetClient(ctx, cid)
			if err != nil {
				return err
			}
			cl := ClientFromRow(cr)
			out.Client = &cl
		}
		if _, err := svc.audit.Append(ctx, tx, audit.Event{Actor: ch.Actor, TenantID: sc.TenantID(), Action: "application.created",
			Target: audit.Target{Type: "application", ID: id}, Details: map[string]any{"slug": p.Slug, "kind": p.Kind}}); err != nil {
			return err
		}
		if _, err := outbox.Enqueue(ctx, tx, outbox.Event{Area: "apps", Entity: "application", Action: "created", TenantID: sc.TenantID(),
			Payload: map[string]any{"app_id": id, "slug": p.Slug, "kind": p.Kind}}); err != nil {
			return err
		}
		r, err := tx.Q.GetApplication(ctx, db.GetApplicationParams{TenantID: sc.TenantID(), ID: id})
		out.App = AppFromRow(r)
		return err
	})
	if err != nil {
		return Created{}, err
	}
	return out, nil
}

func nonNil(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

// Get returns an application of the scoped tenant with its client (if any).
func (svc *Service) Get(ctx context.Context, sc tenancy.Scope, id string) (Application, *Client, error) {
	if !sc.Valid() {
		return Application{}, nil, tenancy.ErrNoAccess
	}
	r, err := svc.s.R().GetApplication(ctx, db.GetApplicationParams{TenantID: sc.TenantID(), ID: id})
	if errors.Is(err, sql.ErrNoRows) {
		return Application{}, nil, ErrAppNotFound
	}
	if err != nil {
		return Application{}, nil, err
	}
	var cl *Client
	if c, err := svc.s.R().GetClientByApp(ctx, id); err == nil {
		x := ClientFromRow(c)
		cl = &x
	}
	return AppFromRow(r), cl, nil
}

// List returns the scoped tenant's applications.
func (svc *Service) List(ctx context.Context, sc tenancy.Scope) ([]Application, error) {
	if !sc.Valid() {
		return nil, tenancy.ErrNoAccess
	}
	rows, err := svc.s.R().ListApplications(ctx, sc.TenantID())
	if err != nil {
		return nil, err
	}
	out := make([]Application, 0, len(rows))
	for _, r := range rows {
		out = append(out, AppFromRow(r))
	}
	return out, nil
}

// UpdateParams change an application; nil fields are unchanged.
type UpdateParams struct {
	Name        *string
	Description *string
	LaunchURL   *string
	Enabled     *bool
	Disclosure  *Disclosure
	Client      *ClientParams // replaces the client configuration (type cannot change)
	IfVersion   int64
}

// Update modifies an application and its client.
func (svc *Service) Update(ctx context.Context, ch domain.Change, sc tenancy.Scope, id string, p UpdateParams) (Application, *Client, error) {
	if !sc.Valid() {
		return Application{}, nil, tenancy.ErrNoAccess
	}
	err := svc.s.W().TxNamed(ctx, "apps.update", func(tx *store.Tx) error {
		r, err := tx.Q.GetApplication(ctx, db.GetApplicationParams{TenantID: sc.TenantID(), ID: id})
		if errors.Is(err, sql.ErrNoRows) {
			return ErrAppNotFound
		}
		if err != nil {
			return err
		}
		if err := domain.IfMatch(p.IfVersion, r.Version); err != nil {
			return err
		}
		a := AppFromRow(r)
		var v apperr.Validation
		if p.Name != nil {
			a.Name = domain.CleanName("name", *p.Name, &v)
		}
		if p.Description != nil {
			a.Description = *p.Description
		}
		if p.LaunchURL != nil {
			a.LaunchURL = *p.LaunchURL
		}
		if p.Enabled != nil {
			a.Enabled = *p.Enabled
		}
		if p.Disclosure != nil {
			a.Disclosure = *p.Disclosure
		}
		var cr db.OauthClient
		if p.Client != nil {
			if cr, err = tx.Q.GetClientByApp(ctx, id); err != nil {
				return ErrClientNotFound
			}
			p.Client.Type = cr.ClientType
			p.Client.ApplicationType = cr.ApplicationType
			svc.validateClient(p.Client, &v)
		}
		if err := v.Err(); err != nil {
			return err
		}
		enabled := int64(0)
		if a.Enabled {
			enabled = 1
		}
		if _, err := tx.Q.UpdateApplication(ctx, db.UpdateApplicationParams{Name: a.Name, Description: a.Description, LaunchUrl: a.LaunchURL, Enabled: enabled,
			DisclosureJson: mustJSON(a.Disclosure), ManagedBy: ch.Managed(), LastChangedBy: domain.NullStr(ch.ChangedBy()), UpdatedAt: tx.NowMicros(),
			TenantID: sc.TenantID(), ID: id, Version: r.Version}); err != nil {
			return err
		}
		if p.Client != nil {
			c := p.Client
			pkce := cr.RequirePkce
			if c.RequirePKCE != nil {
				pkce = 0
				if *c.RequirePKCE || cr.ClientType == "public" {
					pkce = 1
				}
			}
			if _, err := tx.Q.UpdateClient(ctx, db.UpdateClientParams{RedirectUris: mustJSON(nonNil(c.RedirectURIs)), PostLogoutUris: mustJSON(nonNil(c.PostLogoutURIs)),
				GrantTypes: mustJSON(c.GrantTypes), AllowedScopes: mustJSON(c.AllowedScopes), Audiences: mustJSON(nonNil(c.Audiences)),
				AllowedOrigins: mustJSON(nonNil(c.AllowedOrigins)), RequirePkce: pkce, SigningAlg: c.SigningAlg,
				AccessTokenTtlSecs: int64(c.AccessTokenTTL / time.Second), IDTokenTtlSecs: int64(c.IDTokenTTL / time.Second),
				RefreshTtlSecs: int64(c.RefreshTTL / time.Second), RefreshIdleSecs: int64(c.RefreshIdle / time.Second), UpdatedAt: tx.NowMicros(),
				ID: cr.ID, Version: cr.Version}); err != nil {
				return err
			}
		}
		if _, err := svc.audit.Append(ctx, tx, audit.Event{Actor: ch.Actor, TenantID: sc.TenantID(), Action: "application.updated",
			Target: audit.Target{Type: "application", ID: id}, Details: map[string]any{"enabled": a.Enabled, "client_changed": p.Client != nil}}); err != nil {
			return err
		}
		_, err = outbox.Enqueue(ctx, tx, outbox.Event{Area: "apps", Entity: "application", Action: "updated", TenantID: sc.TenantID(),
			Payload: map[string]any{"app_id": id}})
		return err
	})
	if err != nil {
		return Application{}, nil, err
	}
	return svc.Get(ctx, sc, id)
}

// RotateSecret issues a new client secret (shown once); the old one stops working immediately.
func (svc *Service) RotateSecret(ctx context.Context, ch domain.Change, sc tenancy.Scope, appID string) (string, error) {
	if !sc.Valid() {
		return "", tenancy.ErrNoAccess
	}
	secret, mac, hint, err := svc.newSecret()
	if err != nil {
		return "", err
	}
	err = svc.s.W().TxNamed(ctx, "apps.rotate_secret", func(tx *store.Tx) error {
		c, err := tx.Q.GetClientByApp(ctx, appID)
		if err != nil || c.TenantID != sc.TenantID() {
			return ErrClientNotFound
		}
		n, err := tx.Q.SetClientSecret(ctx, db.SetClientSecretParams{SecretMac: mac, SecretHint: hint, UpdatedAt: tx.NowMicros(), ID: c.ID})
		if err != nil {
			return err
		}
		if n != 1 {
			return apperr.New(apperr.CodeConflict, "public clients have no secret")
		}
		_, err = svc.audit.Append(ctx, tx, audit.Event{Actor: ch.Actor, TenantID: sc.TenantID(), Action: "client.secret_rotated",
			Target: audit.Target{Type: "oauth_client", ID: c.ID}})
		return err
	})
	return secret, err
}

// Delete removes an application, its client and every token issued to it.
func (svc *Service) Delete(ctx context.Context, ch domain.Change, sc tenancy.Scope, id string, ifVersion int64) error {
	if !sc.Valid() {
		return tenancy.ErrNoAccess
	}
	return svc.s.W().TxNamed(ctx, "apps.delete", func(tx *store.Tx) error {
		r, err := tx.Q.GetApplication(ctx, db.GetApplicationParams{TenantID: sc.TenantID(), ID: id})
		if errors.Is(err, sql.ErrNoRows) {
			return ErrAppNotFound
		}
		if err != nil {
			return err
		}
		if err := domain.IfMatch(ifVersion, r.Version); err != nil {
			return err
		}
		if _, err := tx.Q.DeleteApplication(ctx, db.DeleteApplicationParams{TenantID: sc.TenantID(), ID: id, Version: r.Version}); err != nil {
			return err
		}
		_, err = svc.audit.Append(ctx, tx, audit.Event{Actor: ch.Actor, TenantID: sc.TenantID(), Action: "application.deleted",
			Target: audit.Target{Type: "application", ID: id}, Details: map[string]any{"slug": r.Slug}})
		return err
	})
}
